import React, { useState, useMemo } from 'react';
import { FiSearch } from 'react-icons/fi';

const RevenueAnalytics = () => {
  const [range, setRange] = useState('month');
  const [search, setSearch] = useState('');
  const [filterType, setFilterType] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize] = useState(15);

  const transactions = [
    { id: 1, user: 'John Doe', type: 'Subscription', amount: 9.99, status: 'Completed', date: '2026-03-30', method: 'Credit Card' },
    { id: 2, user: 'Jane Smith', type: 'Premium Upgrade', amount: 19.99, status: 'Completed', date: '2026-03-30', method: 'PayPal' },
    { id: 3, user: 'Bob Johnson', type: 'Subscription', amount: 9.99, status: 'Completed', date: '2026-03-29', method: 'Mobile Money' },
    { id: 4, user: 'Alice Williams', type: 'One-time Purchase', amount: 24.99, status: 'Completed', date: '2026-03-29', method: 'Credit Card' },
    { id: 5, user: 'Charlie Brown', type: 'Subscription', amount: 9.99, status: 'Failed', date: '2026-03-28', method: 'Credit Card' },
    { id: 6, user: 'Diana Prince', type: 'Premium Upgrade', amount: 19.99, status: 'Completed', date: '2026-03-28', method: 'Bank Transfer' },
    { id: 7, user: 'Eve Davis', type: 'Subscription', amount: 9.99, status: 'Completed', date: '2026-03-27', method: 'PayPal' },
    { id: 8, user: 'Frank Miller', type: 'One-time Purchase', amount: 14.99, status: 'Completed', date: '2026-03-27', method: 'Mobile Money' },
    { id: 9, user: 'Grace Lee', type: 'Subscription', amount: 9.99, status: 'Completed', date: '2026-03-26', method: 'Credit Card' },
    { id: 10, user: 'Henry Wilson', type: 'Premium Upgrade', amount: 19.99, status: 'Pending', date: '2026-03-26', method: 'PayPal' },
  ];

  const filteredRows = useMemo(() => {
    return transactions.filter(item =>
      (filterType ? item.type === filterType : true) &&
      (search ? item.user?.toLowerCase().includes(search.toLowerCase()) ||
               item.method?.toLowerCase().includes(search.toLowerCase()) : true)
    );
  }, [filterType, search]);

  const paginatedRows = useMemo(() => {
    const start = (page - 1) * pageSize;
    return filteredRows.slice(start, start + pageSize);
  }, [filteredRows, page, pageSize]);

  const totalPages = Math.ceil(filteredRows.length / pageSize);

  const getStatusColor = (status) => {
    switch(status) {
      case 'Completed': return '#00a884';
      case 'Pending': return '#fbbf24';
      case 'Failed': return '#ea4335';
      default: return '#8696a0';
    }
  };

  const stats = [
    { label: 'Total Revenue', value: '$2,458.50', change: '+12.5%' },
    { label: 'Total Transactions', value: transactions.filter(t => t.status === 'Completed').length, change: '+8' },
    { label: 'Avg Transaction', value: '$24.83', change: '+2.3%' },
    { label: 'Conversion Rate', value: '3.2%', change: '+0.5%' },
  ];

  return (
    <div className="panel">
      <div className="panel-title">Revenue Analytics</div>
      
      {/* Stats */}
      <div style={{ display: 'flex', gap: 20, marginBottom: 12, flexWrap: 'nowrap', overflowX: 'auto', paddingBottom: 6 }}>
        {stats.map((stat, idx) => (
          <div key={idx} style={{ padding: '2px 8px', background: 'rgba(0, 217, 115, 0.1)', border: '0.25px solid rgba(0, 217, 115, 0.3)', borderRadius: 4, minWidth: 'fit-content', textAlign: 'center', flexShrink: 0 }}>
            <div style={{ fontSize: 8, color: '#8696a0', marginBottom: 0.5, fontWeight: 600 }}>
              {stat.label}
            </div>
            <div style={{ fontSize: 12, fontWeight: 700, color: '#e9edef', marginBottom: 0.5 }}>
              {stat.value}
            </div>
            <div style={{ fontSize: 9, color: '#00d973', fontWeight: 600 }}>
              {stat.change}
            </div>
          </div>
        ))}
      </div>

      {/* Date Range Tabs */}
      <div style={{ marginBottom: 8, display: 'flex', gap: 4, justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', gap: 20, flexWrap: 'wrap' }}>
          {['daily', 'week', 'month', 'year'].map((key) => (
            <button
              key={key}
              className="btn"
              style={{
                padding: '4px 12px',
                borderRadius: 6,
                background: range === key ? '#005c4b' : '#202c33',
                color: '#e9edef',
                border: 'none',
                fontSize: 12,
                textTransform: 'capitalize',
              }}
              onClick={() => setRange(key)}
            >
              {key}
            </button>
          ))}
        </div>
        <div style={{ color: '#8696a0', fontSize: 12 }}>
          {filteredRows.length} transactions
        </div>
      </div>

      {/* Search and Filter */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 8, flexWrap: 'nowrap', alignItems: 'center' }}>
        <div style={{ position: 'relative', flex: '1 1 auto', minWidth: '150px' }}>
          <FiSearch style={{ position: 'absolute', left: 8, top: '50%', transform: 'translateY(-50%)', color: '#8696a0', fontSize: '14px' }} />
          <input
            type="text"
            placeholder="Search by user or method..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="input"
            style={{ paddingLeft: 32, width: '100%', backgroundColor: 'black', color: 'white', fontSize: '13px' }}
          />
        </div>
        <select
          className="select"
          value={filterType}
          onChange={(e) => {
            setFilterType(e.target.value);
            setPage(1);
          }}
          style={{ minWidth: 120, width: 'auto', flexShrink: 0 }}
        >
          <option value="">All Types</option>
          <option value="Subscription">Subscription</option>
          <option value="Premium Upgrade">Premium Upgrade</option>
          <option value="One-time Purchase">One-time Purchase</option>
        </select>
      </div>

      {/* Table */}
      <div style={{ overflowX: 'auto', width: '100%' }}>
        <table className="table">
          <thead>
            <tr>
              <th style={{ textAlign: 'center' }}>ID</th>
              <th>User</th>
              <th>Type</th>
              <th>Status</th>
              <th>Method</th>
              <th>Date</th>
              <th>Amount</th>
            </tr>
          </thead>
          <tbody>
            {paginatedRows.length === 0 ? (
              <tr><td colSpan={7} style={{ color: '#8696a0', textAlign: 'center' }}>No transactions found</td></tr>
            ) : paginatedRows.map((transaction, idx) => (
              <tr key={transaction.id}>
                <td style={{ fontSize: '13px', fontWeight: '600', color: '#00a884', textAlign: 'center' }}>
                  {(page - 1) * pageSize + idx + 1}
                </td>
                <td style={{ fontWeight: '500' }}>
                  {transaction.user}
                </td>
                <td style={{ fontSize: '12px', color: '#8696a0' }}>
                  {transaction.type}
                </td>
                <td>
                  <span style={{
                    fontSize: 11,
                    fontWeight: 700,
                    color: getStatusColor(transaction.status),
                    textTransform: 'none'
                  }}>
                    {transaction.status}
                  </span>
                </td>
                <td style={{ fontSize: '12px', color: '#8696a0' }}>
                  {transaction.method}
                </td>
                <td style={{ fontSize: '12px', color: '#8696a0' }}>
                  {new Date(transaction.date).toLocaleDateString()}
                </td>
                <td style={{ fontWeight: '600', color: '#00d973' }}>
                  ${transaction.amount.toFixed(2)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div style={{ display: 'flex', gap: 8, marginTop: 8, justifyContent: 'center', alignItems: 'center' }}>
          <button
            className="btn"
            disabled={page === 1}
            onClick={() => setPage(p => Math.max(1, p - 1))}
            style={{ padding: '4px 12px', fontSize: '12px' }}
          >
            Prev
          </button>
          <span style={{ color: '#8696a0', fontSize: 12 }}>
            Page {page} of {totalPages}
          </span>
          <button
            className="btn"
            disabled={page === totalPages}
            onClick={() => setPage(p => Math.min(totalPages, p + 1))}
            style={{ padding: '4px 12px', fontSize: '12px' }}
          >
            Next
          </button>
        </div>
      )}
    </div>
  );
};

export default RevenueAnalytics;

